boss_trace.js.src:
function parseAge(text) {
  const n = Number(text);
  if (Number.isNaN(n)) throw new TypeError("not a number");
  if (n < 0 || n > 120) throw new RangeError("out of range");
  return n;
}
for (const text of ["12", "abc", "-4", "130", "40"]) {
  let result;
  try {
    result = parseAge(text);
  } catch (err) {
    result = err.name;
  }
  console.log(text, result);
}

